/** Practical applications of shared teaching, authored for the chosen pressure goal. */
import type { GoalLessonContext } from './goalLessonVariants';

type PressureContextEntry = readonly [
  title: string, explanation: string, step: string, action: string, alternative: string,
];

const CHAPTER_TITLES: Readonly<Record<string, string>> = {
  'Name the Uncertain Feeling': 'Name What You Feel',
  'Walk With an Open Question': 'Walk With Uncertainty',
  'Quiet the Checking Prompts': 'Quiet Checking Prompts',
  'Address the Actual Mistake': 'Repair What Happened',
  'Prepare Without Perfecting': 'Prepare, Then Begin',
  'Make Space Before Reacting': 'Space Before a Reply',
  'Respond Without Self-Blame': 'Respond Without Blame',
  'Support Tomorrow’s Patience': 'Tomorrow’s Patience',
  'Notice the Evening Pattern': 'Your Evening Pattern',
  'Choose the Conversation Time': 'Choose When to Talk',
  'Return to Practising Patience': 'Return to Patience',
};

function contexts<const Entries extends Record<string, PressureContextEntry>>(entries: Entries): { [Key in keyof Entries]: GoalLessonContext } {
  return Object.fromEntries(Object.entries(entries).map(([id, [title, explanation, step, action, alternative]]) => [id, {
    title,
    chapterTitle: CHAPTER_TITLES[title] ?? title,
    explanation,
    step,
    action,
    prompt: 'Which response applies this idea to the situation described?',
    alternative,
    alternativeFeedback: action.replace(/\*\*/g, ''),
  }])) as { [Key in keyof Entries]: GoalLessonContext };
}

